 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8" />
   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
   <title>Notification Preferences</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1020;
       --panel: rgba(17, 24, 39, 0.88);
       --panel-border: rgba(148, 163, 184, 0.18);
       --text: #e5eefc;
       --muted: #94a3b8;
       --accent: #60a5fa;
       --accent-strong: #3b82f6;
       --shadow: 0 28px 60px rgba(0, 0, 0, 0.45);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       display: grid;
       place-items: center;
       padding: 24px;
       font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, rgba(59, 130, 246, 0.22), transparent 30%),
         linear-gradient(180deg, #111827 0%, #020617 100%);
       color: var(--text);
     }

     .app-shell {
       width: min(100%, 520px);
       background: var(--panel);
       border: 1px solid var(--panel-border);
       border-radius: 24px;
       padding: 32px;
       box-shadow: var(--shadow);
       backdrop-filter: blur(18px);
     }

     .eyebrow {
       margin: 0 0 8px;
       font-size: 0.8rem;
       letter-spacing: 0.16em;
       text-transform: uppercase;
       color: var(--accent);
     }

     h1 {
       margin: 0;
       font-size: clamp(1.8rem, 4vw, 2.4rem);
       line-height: 1.1;
     }

     .intro {
       margin: 12px 0 0;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       margin-top: 28px;
       display: grid;
       gap: 20px;
     }

     .form-field {
       display: grid;
       gap: 14px;
       padding: 20px;
       border-radius: 18px;
       background: rgba(15, 23, 42, 0.75);
       border: 1px solid rgba(148, 163, 184, 0.12);
     }

     .field-label {
       font-size: 1rem;
       font-weight: 600;
     }

     .options {
       display: grid;
       gap: 12px;
     }

     .radio-card {
       display: flex;
       align-items: center;
       gap: 12px;
       padding: 14px 16px;
       border: 1px solid rgba(148, 163, 184, 0.14);
       border-radius: 14px;
       background: rgba(30, 41, 59, 0.62);
       transition: border-color 160ms ease, transform 160ms ease, background 160ms ease;
       cursor: pointer;
     }

     .radio-card:hover {
       transform: translateY(-1px);
       border-color: rgba(96, 165, 250, 0.38);
       background: rgba(37, 99, 235, 0.12);
     }

     .radio-card input[type="radio"] {
       accent-color: var(--accent-strong);
       width: 18px;
       height: 18px;
       margin: 0;
       flex: 0 0 auto;
     }

     .radio-text {
       font-size: 0.98rem;
       font-weight: 500;
     }

     .submit-button {
       border: 0;
       border-radius: 14px;
       padding: 14px 18px;
       font: inherit;
       font-weight: 700;
       color: #eff6ff;
       background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
       box-shadow: 0 14px 30px rgba(37, 99, 235, 0.35);
       cursor: pointer;
       transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
     }

     .submit-button:hover {
       transform: translateY(-1px);
       box-shadow: 0 18px 32px rgba(37, 99, 235, 0.42);
       filter: brightness(1.03);
     }

     .submit-button:active {
       transform: translateY(0);
     }
   </style>
 </head>
 <body>
   <div id="app"></div>

   <script>
     const notificationOptions = [
       { value: "email", label: "Email" },
       { value: "sms", label: "SMS" },
       { value: "push", label: "Push Notifications" }
     ];

     function RadioOption({ name, option }) {
       return `
         <label class="radio-card">
           <input type="radio" name="${name}" value="${option.value}" required />
           <span class="radio-text">${option.label}</span>
         </label>
       `;
     }

     function FormField({ label, name, options }) {
       return `
         <div class="form-field">
           <div class="field-label">${label}</div>
           <div class="options">
             ${options.map((option) => RadioOption({ name, option })).join("")}
           </div>
         </div>
       `;
     }

     function App() {
       return `
         <main class="app-shell">
           <p class="eyebrow">Preferences</p>
           <h1>Stay in the loop</h1>
           <p class="intro">Choose the best way for us to send updates about your account and activity.</p>
           <form>
             ${FormField({
               label: "How do you prefer to receive notifications?",
               name: "notificationPreference",
               options: notificationOptions
             })}
             <button class="submit-button" type="submit">Submit</button>
           </form>
         </main>
       `;
     }

     document.getElementById("app").innerHTML = App();
   </script>
 </body>
 </html>

